package net.civeira.phylax.features.document.theme.domain.gateway;

import java.util.List;
import java.util.Optional;

import lombok.Builder;
import lombok.Data;
import lombok.EqualsAndHashCode;
import lombok.With;
import net.civeira.phylax.features.access.tenant.domain.TenantRef;

@Data
@Builder(toBuilder = true)
@With
@EqualsAndHashCode(onlyExplicitlyIncluded = true)
public class ThemeFilter {

  /**
   * Filter by the unique index name, tenant
   *
   * @autogenerated FilterGenerator
   * @param name
   * @param tenant
   * @return
   */
  public static ThemeFilter byNameAndTenant(final String name, final TenantRef tenant) {
    return builder().name(name).tenant(tenant).build();
  }

  /**
   * @autogenerated FilterGenerator
   */
  private Boolean global;

  /**
   * @autogenerated FilterGenerator
   */
  private String name;

  /**
   * The filter to select the results to retrieve
   *
   * @autogenerated FilterGenerator
   */
  private String search;

  /**
   * @autogenerated FilterGenerator
   */
  private TenantRef tenant;

  /**
   * @autogenerated FilterGenerator
   */
  private String tenantAccessible;

  /**
   * @autogenerated FilterGenerator
   */
  private List<String> tenants;

  /**
   * The filter to select the results to retrieve
   *
   * @autogenerated FilterGenerator
   */
  private String uid;

  /**
   * The filter to select the results to retrieve
   *
   * @autogenerated FilterGenerator
   */
  private List<String> uids;

  /**
   * @autogenerated FilterGenerator
   * @return
   */
  public Optional<Boolean> getGlobal() {
    return Optional.ofNullable(global);
  }

  /**
   * @autogenerated FilterGenerator
   * @return
   */
  public Optional<String> getName() {
    return Optional.ofNullable(name);
  }

  /**
   * @autogenerated FilterGenerator
   * @return
   */
  public Optional<String> getSearch() {
    return Optional.ofNullable(search);
  }

  /**
   * @autogenerated FilterGenerator
   * @return
   */
  public Optional<TenantRef> getTenant() {
    return Optional.ofNullable(tenant);
  }

  /**
   * @autogenerated FilterGenerator
   * @return
   */
  public Optional<String> getTenantAccessible() {
    return Optional.ofNullable(tenantAccessible);
  }

  /**
   * @autogenerated FilterGenerator
   * @return
   */
  public List<String> getTenants() {
    return null == tenants ? List.of() : List.copyOf(tenants);
  }

  /**
   * @autogenerated FilterGenerator
   * @return
   */
  public Optional<String> getUid() {
    return Optional.ofNullable(uid);
  }

  /**
   * @autogenerated FilterGenerator
   * @return
   */
  public List<String> getUids() {
    return null == uids ? List.of() : List.copyOf(uids);
  }
}
